package ch.adeon.apps.docextract.agentgateway.application;

import java.util.List;

/**
 * Inbound port of the agent path (FR-6): read-only queries on a process of the caller's tenant.
 * There is deliberately no confirm/DMS-write operation (C-2, ADR-003).
 */
public interface McpTool {

  String GET_PROCESS_SUGGESTIONS = "get_process_suggestions";
  String FIND_SIMILAR_DOCUMENTS = "find_similar_documents";

  /** Canonical lowercase UUID, as generated by {@code IngestDocumentService}. */
  String PROCESS_ID_PATTERN = "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$";

  ProcessSuggestions getProcessSuggestions(String processId);

  List<SimilarDocument> findSimilarDocuments(String processId);
}
